// Typed access to data/model-artifacts.json, generated by `python -m ml_models.export_artifacts`.
import raw from '@/data/model-artifacts.json';
import type { ProcessParameters, ScenarioConfig } from '@/lib/simulation/types';

export interface FeatureImportance {
  feature: string;
  importance: number;
}

export interface SatisfactionSurface {
  experience_bands: number[];
  delays: number[];
  mean_probability: number[][];
  satisfied_share: number[][];
  profiles_sampled: number;
}

export interface TrafficPoint {
  month: string;
  passengers: number;
}

export interface BacktestPoint {
  month: string;
  actual: number;
  lstm: number;
  seasonal_naive: number;
}

interface ForecastMetrics {
  mae: number;
  rmse: number;
  mape: number;
}

export interface ModelArtifacts {
  generated_at: string;
  parameters: ProcessParameters;
  defaults: ScenarioConfig;
  bounds: Record<string, [number, number]>;
  airlines: string[];
  delay_distribution: { source: string; n: number; mean: number; on_time_share: number; quantiles: number[] };
  satisfaction_surface: SatisfactionSurface | null;
  models: {
    satisfaction: {
      model: string;
      task: string;
      dataset: string;
      train_rows: number;
      test_rows: number;
      metrics: {
        accuracy: number;
        precision: number;
        recall: number;
        f1: number;
        roc_auc: number;
        baseline_accuracy: number;
      };
      train_seconds: number;
      inference_ms_per_row: number;
      feature_importance: FeatureImportance[];
      hyperparameters: Record<string, number>;
      trained_at: string;
    };
    delay: { model: string; metrics: Record<string, number>; train_rows: number; test_rows: number; split: string } | null;
    traffic: {
      model: string;
      airport: string;
      look_back_months: number;
      test_months: number;
      epochs_run: number;
      train_seconds: number;
      metrics: { lstm: ForecastMetrics; seasonal_naive: ForecastMetrics };
      trained_at: string;
    };
  };
  traffic: {
    history: TrafficPoint[];
    backtest: BacktestPoint[];
    forecast: TrafficPoint[];
    seasonal_index: Record<string, number>;
  };
}

export const artifacts = raw as unknown as ModelArtifacts;
